/// The library's base. Its methods are the library's functions, and
/// each calls through the jump table.
pub const DosBase = opaque {
    /// The Library header at the base.
    pub fn lib(self: *DosBase) *libraries.Library {
        return @ptrCast(@alignCast(self));
    }

    /// Send a packet (action, up to five arguments) to the handler at `port`
    /// and wait for it to come back. Returns dp_Res1; a process gets dp_Res2
    /// from IoErr(). Works from a plain task too, with a port of its own for
    /// the reply. Other packets that come back meanwhile are kept for the
    /// caller.
    pub fn DoPkt(self: *DosBase, port: *exec.MsgPort, action: i32, arg1: isize, arg2: isize, arg3: isize, arg4: isize, arg5: isize) isize {
        return libraries.call(self, LVO.DoPkt, Fn.DoPkt, .{ port, action, arg1, arg2, arg3, arg4, arg5 });
    }

    /// Send a packet to `port` without waiting; it comes back to `reply_port`
    /// (your process's msg_port, to get it with WaitPkt). Callable from tasks.
    pub fn SendPkt(self: *DosBase, packet: *dos.DosPacket, port: *exec.MsgPort, reply_port: *exec.MsgPort) void {
        return libraries.call(self, LVO.SendPkt, Fn.SendPkt, .{ packet, port, reply_port });
    }

    /// Wait for a packet at your process's msg_port (through pr_PktWait if
    /// set) and take it off the port. Null from a plain task.
    pub fn WaitPkt(self: *DosBase) ?*dos.DosPacket {
        return libraries.call(self, LVO.WaitPkt, Fn.WaitPkt, .{});
    }

    /// Send a packet back to its sender with res1 and res2. Its dp_Port becomes
    /// your msg_port, so a ReplyPkt from there returns it to you. Null does
    /// nothing.
    pub fn ReplyPkt(self: *DosBase, packet: ?*dos.DosPacket, res1: isize, res2: i32) void {
        return libraries.call(self, LVO.ReplyPkt, Fn.ReplyPkt, .{ packet, res1, res2 });
    }

    /// Ask for a packet sent with SendPkt to be aborted. Does nothing: wait
    /// for the packet to come back all the same.
    pub fn AbortPkt(self: *DosBase, port: *exec.MsgPort, packet: *dos.DosPacket) void {
        return libraries.call(self, LVO.AbortPkt, Fn.AbortPkt, .{ port, packet });
    }

    /// A dos object of `obj_type` (DOS_*): so far DOS_STDPKT, a cleared
    /// DosPacket. Null for no memory (ERROR_NO_FREE_STORE), a type not done
    /// yet (ERROR_NOT_IMPLEMENTED) or an unknown one.
    pub fn AllocDosObject(self: *DosBase, obj_type: u32, tags: ?[*]const utility.TagItem) ?*anyopaque {
        return libraries.call(self, LVO.AllocDosObject, Fn.AllocDosObject, .{ obj_type, tags });
    }

    /// Free an object from AllocDosObject, given its type. Null does nothing.
    pub fn FreeDosObject(self: *DosBase, obj_type: u32, ptr: ?*anyopaque) void {
        return libraries.call(self, LVO.FreeDosObject, Fn.FreeDosObject, .{ obj_type, ptr });
    }

    /// The secondary result of the last dos call (pr_Result2);
