    }

    /// Free what MatchFirst and MatchNext hold.
    pub fn MatchEnd(self: *DosBase, anchor: *dos.AnchorPath) void {
        return libraries.call(self, LVO.MatchEnd, Fn.MatchEnd, .{anchor});
    }

    /// Rename or move `from` to `to` on the same volume ("RAM:a" to
    /// "RAM:d/b"): ERROR_RENAME_ACROSS_DEVICES for another handler,
    /// ERROR_OBJECT_EXISTS if `to` is there.
    pub fn Rename(self: *DosBase, from: [*:0]const u8, to: [*:0]const u8) bool {
        return libraries.call(self, LVO.Rename, Fn.Rename, .{ from, to });
    }

    /// Set the protection bits (FIBF_*; the low four are set to forbid).
    pub fn SetProtection(self: *DosBase, name: [*:0]const u8, bits: u32) bool {
        return libraries.call(self, LVO.SetProtection, Fn.SetProtection, .{ name, bits });
    }

    /// Set the comment: at most 79 characters, "" removes it.
    pub fn SetComment(self: *DosBase, name: [*:0]const u8, comment: [*:0]const u8) bool {
        return libraries.call(self, LVO.SetComment, Fn.SetComment, .{ name, comment });
    }

    /// Set the date (DateStamp()'s, say).
    pub fn SetFileDate(self: *DosBase, name: [*:0]const u8, date: *const dos.DateStamp) bool {
        return libraries.call(self, LVO.SetFileDate, Fn.SetFileDate, .{ name, date });
    }

    /// Set the owner: user << 16 | group.
    pub fn SetOwner(self: *DosBase, name: [*:0]const u8, owner_info: u32) bool {
        return libraries.call(self, LVO.SetOwner, Fn.SetOwner, .{ name, owner_info });
    }

    /// Cut or grow an open file to `offset` from OFFSET_BEGINNING,
    /// OFFSET_CURRENT or OFFSET_END; new bytes are 0. The new size, or -1.
    pub fn SetFileSize(self: *DosBase, file: ?*dos.FileHandle, offset: isize, mode: i32) isize {
        return libraries.call(self, LVO.SetFileSize, Fn.SetFileSize, .{ file, offset, mode });
    }

    /// A shared lock on an open file.
    pub fn DupLockFromFH(self: *DosBase, file: ?*dos.FileHandle) ?*dos.FileLock {
        return libraries.call(self, LVO.DupLockFromFH, Fn.DupLockFromFH, .{file});
    }

    /// A shared lock on the directory an open file is in.
    pub fn ParentOfFH(self: *DosBase, file: ?*dos.FileHandle) ?*dos.FileLock {
        return libraries.call(self, LVO.ParentOfFH, Fn.ParentOfFH, .{file});
    }

    /// The full name of an open file, as NameFromLock.
    pub fn NameFromFH(self: *DosBase, file: ?*dos.FileHandle, buffer: [*]u8, size: u32) bool {
        return libraries.call(self, LVO.NameFromFH, Fn.NameFromFH, .{ file, buffer, size });
    }

    /// An open file from a lock on a file; the lock is the file's from then
    /// on (on failure it stays yours).
    pub fn OpenFromLock(self: *DosBase, lock: ?*dos.FileLock) ?*dos.FileHandle {
        return libraries.call(self, LVO.OpenFromLock, Fn.OpenFromLock, .{lock});
    }

    /// A lock (CHANGE_LOCK: SHARED_LOCK or EXCLUSIVE_LOCK) or an open file
    /// (CHANGE_FH: MODE_NEWFILE exclusive, else shared) to another access;
    /// ERROR_OBJECT_IN_USE while others hold it.
    pub fn ChangeMode(self: *DosBase, kind: i32, object: ?*anyopaque, mode: i32) bool {
        return libraries.call(self, LVO.ChangeMode, Fn.ChangeMode, .{ kind, object, mode });
    }

    /// The volume a lock is on, in `data` (lock 0: the current file system).
    pub fn Info(self: *DosBase, lock: ?*dos.FileLock, data: *dos.InfoData) bool {
        return libraries.call(self, LVO.Info, Fn.Info, .{ lock, data });
    }

    /// Whether a name's handler is a file system ("*" isn't; a name without a
    /// device is).
    pub fn IsFileSystem(self: *DosBase, name: [*:0]const u8) bool {
        return libraries.call(self, LVO.IsFileSystem, Fn.IsFileSystem, .{name});
    }

    /// Whether two locks are on one device: the same volume or handler.
    pub fn SameDevice(self: *DosBase, lock1: ?*dos.FileLock, lock2: ?*dos.FileLock) bool {
        return libraries.call(self, LVO.SameDevice, Fn.SameDevice, .{ lock1, lock2 });
    }

    /// Hand back what the buffer holds: waiting bytes are written, bytes read
    /// ahead given back (seeked back over). False, with
    /// IoErr, when writing fails.
    pub fn Flush(self: *DosBase, file: ?*dos.FileHandle) bool {
        return libraries.call(self, LVO.Flush, Fn.Flush, .{file});
    }

    /// The next byte (0-255), or -1 at the end (IoErr 0) or on an error.
    pub fn FGetC(self: *DosBase, file: ?*dos.FileHandle) i32 {
        return libraries.call(self, LVO.FGetC, Fn.FGetC, .{file});
    }

    /// Push `character` back for the next FGetC; -1 pushes back the last one
    /// FGetC gave (the end too). Up to 4; false when full or nothing to push.
    pub fn UnGetC(self: *DosBase, file: ?*dos.FileHandle, character: i32) bool {
        return libraries.call(self, LVO.UnGetC, Fn.UnGetC, .{ file, character });
    }

    /// Write a byte (the low 8 bits): the byte, or -1 on an error.
    pub fn FPutC(self: *DosBase, file: ?*dos.FileHandle, character: i32) i32 {
        return libraries.call(self, LVO.FPutC, Fn.FPutC, .{ file, character });
    }

    /// Read up to `length` bytes through the buffer: the number read, 0 at the
    /// end, -1 on an error before any byte. A console gives what it has.
    pub fn FRead(self: *DosBase, file: ?*dos.FileHandle, buffer: [*]u8, length: isize) isize {
        return libraries.call(self, LVO.FRead, Fn.FRead, .{ file, buffer, length });
    }

    /// Write `length` bytes through the buffer: `length`, or -1 on an error.
    pub fn FWrite(self: *DosBase, file: ?*dos.FileHandle, buffer: [*]const u8, length: isize) isize {
        return libraries.call(self, LVO.FWrite, Fn.FWrite, .{ file, buffer, length });
    }

    /// A line into `buffer`: at most size-1 bytes, the newline kept, then a
    /// NUL. Null at the end (or on an error) before any byte.
    pub fn FGets(self: *DosBase, file: ?*dos.FileHandle, buffer: [*]u8, size: u32) ?[*]u8 {
        return libraries.call(self, LVO.FGets, Fn.FGets, .{ file, buffer, size });
    }

    /// Write a C string: 0, or -1 on an error.
    pub fn FPuts(self: *DosBase, file: ?*dos.FileHandle, string: [*:0]const u8) i32 {
        return libraries.call(self, LVO.FPuts, Fn.FPuts, .{ file, string });
    }

    /// The buffer's mode (BUF_LINE, BUF_FULL, BUF_NONE) and, unless size is
    /// -1, its size, in `buffer` (the caller's, kept until Close) or allocated
    /// (buffer null). What the old one held is flushed. 0, or -1 with IoErr.
    pub fn SetVBuf(self: *DosBase, file: ?*dos.FileHandle, buffer: ?[*]u8, mode: i32, size: isize) i32 {
        return libraries.call(self, LVO.SetVBuf, Fn.SetVBuf, .{ file, buffer, mode, size });
    }

    /// RawDoFmt's format with its data stream, through FPutC: the bytes
    /// written, or -1. sdk.dos.stdio.FPrintf packs the values.
    pub fn VFPrintf(self: *DosBase, file: ?*dos.FileHandle, format: [*:0]const u8, args: ?*const anyopaque) i32 {
        return libraries.call(self, LVO.VFPrintf, Fn.VFPrintf, .{ file, format, args });
    }

    /// VFPrintf to Output() (sdk.dos.stdio.Printf).
    pub fn VPrintf(self: *DosBase, format: [*:0]const u8, args: ?*const anyopaque) i32 {
        return libraries.call(self, LVO.VPrintf, Fn.VPrintf, .{ format, args });
    }

    /// FPuts to Output().
    pub fn PutStr(self: *DosBase, string: [*:0]const u8) i32 {
        return libraries.call(self, LVO.PutStr, Fn.PutStr, .{string});
    }

    /// FWrite to Output().
    pub fn WriteChars(self: *DosBase, buffer: [*]const u8, length: isize) isize {
        return libraries.call(self, LVO.WriteChars, Fn.WriteChars, .{ buffer, length });
    }

    /// Parse arguments by a template ("FROM/M/A,TO/A,Q=QUIET/S"): /A required,
    /// /K only with its keyword, /S switch, /N number, /T toggle (YES, NO, ON,
    /// OFF), /M many, /F the rest of the line; '=' names aliases. Into `argv`,
    /// one pointer-sized slot per item, set by the caller to defaults: a
    /// string, an i32's address (/N), DOSTRUE (/S, /T), or a null-terminated
    /// array (/M). From `rdargs`'s CSource, else Input(); a null `rdargs`
    /// makes one. Null on failure (IoErr); FreeArgs the result.
    pub fn ReadArgs(self: *DosBase, template: [*:0]const u8, argv: [*]usize, rdargs: ?*dos.RDArgs) ?*dos.RDArgs {
        return libraries.call(self, LVO.ReadArgs, Fn.ReadArgs, .{ template, argv, rdargs });
    }

    /// Free what ReadArgs allocated (its RDArgs too, if it made it). Null is
    /// fine, and so is a second call.
    pub fn FreeArgs(self: *DosBase, rdargs: ?*dos.RDArgs) void {
        return libraries.call(self, LVO.FreeArgs, Fn.FreeArgs, .{rdargs});
    }

    /// The next item from `csource` (Input() without a buffer) into `buffer`
    /// (`maxchars` bytes with the NUL): ITEM_QUOTED, ITEM_UNQUOTED,
    /// ITEM_NOTHING (the line's end), ITEM_EQUAL (a leading '='), ITEM_ERROR.
    pub fn ReadItem(self: *DosBase, buffer: [*]u8, maxchars: i32, csource: ?*dos.CSource) i32 {
        return libraries.call(self, LVO.ReadItem, Fn.ReadItem, .{ buffer, maxchars, csource });
    }

    /// The number of the template item `keyword` names (any alias, any case),
    /// or -1.
    pub fn FindArg(self: *DosBase, template: [*:0]const u8, keyword: [*:0]const u8) i32 {
        return libraries.call(self, LVO.FindArg, Fn.FindArg, .{ template, keyword });
    }

    /// A decimal number (after spaces, with an optional '-') into `value`: the
    /// characters used, or -1 (value 0) without one or beyond an i32.
    pub fn StrToLong(self: *DosBase, string: [*:0]const u8, value: *i32) i32 {
        return libraries.call(self, LVO.StrToLong, Fn.StrToLong, .{ string, value });
    }

    /// A console's mode: 1 raw (bytes as typed, no echo or editing), 0 cooked
    /// (edited lines). What waits in the buffer is written first. False, with
    /// IoErr, when the handler can't.
    pub fn SetMode(self: *DosBase, file: ?*dos.FileHandle, mode: i32) bool {
        return libraries.call(self, LVO.SetMode, Fn.SetMode, .{ file, mode });
    }

    /// Whether a console has input within `timeout` microseconds (cooked: a
    /// whole line); bytes in the handle's buffer count.
    pub fn WaitForChar(self: *DosBase, file: ?*dos.FileHandle, timeout: isize) bool {
        return libraries.call(self, LVO.WaitForChar, Fn.WaitForChar, .{ file, timeout });
    }

    /// The text for an error code (IoErr's; the shell's are negative) after
    /// `header` and ": " into `buffer` (`len` bytes with the NUL, cut to
    /// fit); "Error <n>" for one without a text; nothing for 0. The length.
    pub fn Fault(self: *DosBase, code: i32, header: ?[*:0]const u8, buffer: [*]u8, len: i32) i32 {
        return libraries.call(self, LVO.Fault, Fn.Fault, .{ code, header, buffer, len });
    }

    /// Fault's text and a newline to Output(); IoErr is left at the code.
    /// False without an Output() or when the write fails.
    pub fn PrintFault(self: *DosBase, code: i32, header: ?[*:0]const u8) bool {
        return libraries.call(self, LVO.PrintFault, Fn.PrintFault, .{ code, header });
    }

    /// Set a local variable or alias (LV_VAR or LV_ALIAS in the low byte of
    /// `flags`), or a global one in ENV: with GVF_GLOBAL_ONLY; `size` -1 is
    /// strlen. A null `buffer` deletes it. False, with IoErr, on failure.
    pub fn SetVar(self: *DosBase, name: [*:0]const u8, buffer: ?[*]const u8, size: isize, flags: u32) bool {
        return libraries.call(self, LVO.SetVar, Fn.SetVar, .{ name, buffer, size, flags });
    }

    /// A variable's value into `buffer` (`size` bytes): the local one, else
    /// ENV:'s (unless GVF_LOCAL_ONLY); text is cut at a newline and ends in a
    /// NUL. The bytes copied (IoErr: the whole length), or -1 with IoErr.
    pub fn GetVar(self: *DosBase, name: [*:0]const u8, buffer: [*]u8, size: isize, flags: u32) isize {
        return libraries.call(self, LVO.GetVar, Fn.GetVar, .{ name, buffer, size, flags });
    }

    /// SetVar(name, null, 0, flags).
    pub fn DeleteVar(self: *DosBase, name: [*:0]const u8, flags: u32) bool {
        return libraries.call(self, LVO.DeleteVar, Fn.DeleteVar, .{ name, flags });
    }

    /// A local variable or alias of `var_type` (LV_VAR, LV_ALIAS), or null.
    pub fn FindVar(self: *DosBase, name: [*:0]const u8, var_type: u32) ?*dos.LocalVar {
        return libraries.call(self, LVO.FindVar, Fn.FindVar, .{ name, var_type });
    }

    /// Which of `mask`'s signals came (SIGBREAKF_CTRL_C..F); they are cleared.
    pub fn CheckSignal(self: *DosBase, mask: u32) u32 {
        return libraries.call(self, LVO.CheckSignal, Fn.CheckSignal, .{mask});
    }

    /// Wait `ticks` fiftieths of a second.
    pub fn Delay(self: *DosBase, ticks: u32) void {
        return libraries.call(self, LVO.Delay, Fn.Delay, .{ticks});
    }

    /// The running command's argument line (pr_Arguments), or null.
    pub fn GetArgStr(self: *DosBase) ?[*:0]const u8 {
        return libraries.call(self, LVO.GetArgStr, Fn.GetArgStr, .{});
    }

    /// Set pr_Arguments; the old one.
    pub fn SetArgStr(self: *DosBase, string: ?[*:0]const u8) ?[*:0]const u8 {
        return libraries.call(self, LVO.SetArgStr, Fn.SetArgStr, .{string});
    }

    /// The highest CLI number in use (0: none).
    pub fn MaxCli(self: *DosBase) u32 {
        return libraries.call(self, LVO.MaxCli, Fn.MaxCli, .{});
    }

    /// The CLI process with number `num` (pr_TaskNum), or null.
    pub fn FindCliProc(self: *DosBase, num: u32) ?*dos.Process {
        return libraries.call(self, LVO.FindCliProc, Fn.FindCliProc, .{num});
    }

    /// Run a segment's command on this process, on a stack of its own of
    /// `stack_size` bytes: `args` (`length` bytes, a line ending in a newline)
    /// are Input()'s read-ahead and pr_Arguments meanwhile. The command's
    /// return code, or -1 (IoErr) when it can't run.
    pub fn RunCommand(self: *DosBase, code: ?*const dos.SegCode, stack_size: u32, args: [*]const u8, length: isize) i32 {
        return libraries.call(self, LVO.RunCommand, Fn.RunCommand, .{ code, stack_size, args, length });
    }

    /// Run `command` (a line, or several) in a new shell ("BootShell";
    /// SYS_UserShell: "shell"; SYS_CustomShell: another resident) with
    /// SYS_Input and SYS_Output (default Input(), Output()). Waits and returns
    /// the last return code (IoErr: its Result2), or -1 when it can't start;
    /// with SYS_Asynch it returns at once, with the new CLI's number, and the
    /// shell closes the streams. A null command starts an interactive shell on
    /// SYS_Input. CreateNewProc's tags pass through.
    pub fn SystemTagList(self: *DosBase, command: ?[*:0]const u8, tags: ?[*]const utility.TagItem) i32 {
        return libraries.call(self, LVO.SystemTagList, Fn.SystemTagList, .{ command, tags });
    }

    /// Run `command` in a new shell, then the commands from `input` (if any),
    /// with `output` (null: Output()). True if the shell ran.
    pub fn Execute(self: *DosBase, command: [*:0]const u8, input: ?*dos.FileHandle, output: ?*dos.FileHandle) bool {
        return libraries.call(self, LVO.Execute, Fn.Execute, .{ command, input, output });
    }

    /// Load a program or module file (sdk/libs/dos/loadfile.zig, made by
    /// sdk/tools/elf2seg): its segments into memory the CPU can run, the
    /// addresses in them relocated. Returns the seglist for UnLoadSeg, or null
    /// with IoErr.
    pub fn LoadSeg(self: *DosBase, name: [*:0]const u8) ?*dos.SegList {
        return libraries.call(self, LVO.LoadSeg, Fn.LoadSeg, .{name});
    }

    /// Free what LoadSeg made. Null is allowed.
    pub fn UnLoadSeg(self: *DosBase, seg_list: ?*dos.SegList) void {
        return libraries.call(self, LVO.UnLoadSeg, Fn.UnLoadSeg, .{seg_list});
    }
};
